import std.io

pub type AppError = Failed(String)

foreign "c" {
    byres record CFile { }
    fn weOpen(id: Int64) effect -> CFile
    fn weClose(f: CFile) effect
    fn weCloses() effect -> Int64
}

impl Releasable for CFile {
    fn release(mut self) { weClose(self) }
}

fn pick(id: Int64) -> Int64 {
    scope resource(f = weOpen(id)) {
        if id > 0 { return 7 }
    }
    return 0
}

pub fn main() effect io -> Result<(), AppError> {
    scope resource(a = weOpen(1), b = weOpen(2)) {
        io.println("in")
    }
    io.println("${weCloses()}")
    io.println("${pick(3)}")
    io.println("${weCloses()}")
    return Ok(())
}

