/* The probe's native side: a handle is its id, and the close log is a
   decimal accumulator — the We side reads it back to see the order the
   releases ran in. */
static long closes = 0;
void *weOpen(long id) { return (void *)id; }
void weClose(void *f) { closes = closes * 10 + (long)f; }
long weCloses(void) { return closes; }
